#!/usr/bin/env python3
import hashlib,importlib.util,json,os,pathlib,shlex,subprocess,sys,tempfile,unittest
HERE=pathlib.Path(__file__).resolve().parent
p=HERE/'run-authoritative-service.py';s=importlib.util.spec_from_file_location('supervisor',p);m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
def sha(raw):return hashlib.sha256(raw).hexdigest()
class Tests(unittest.TestCase):
 def test_frozen_package_pins_code_input_accounting_and_exact_owner_command_without_execution(self):
  with tempfile.TemporaryDirectory(prefix='poe-TEST-ONLY-original-package-')as t:
   d=pathlib.Path(t);bundle=d/'bundle';bundle.mkdir(mode=0o700);source={'commit':'a'*40,'sha256':sha(b'fixture-native-no-execution')};bodies={name:b'fixture-no-execution'for name in m.RELEASE_FILES};bodies['native-paper.mjs']=b'fixture-native-no-execution';bodies['metadata.json']=json.dumps({'git':{'commit':source['commit']},'financialMode':'PAPER','liveTradingEnabled':False}).encode()
   for name,raw in bodies.items():(bundle/name).write_bytes(raw)
   manifest={'schemaVersion':1,'kind':'poe-authoritative-persistent-service-v1','source':source,'configurationSha256':'b'*64,'stage':'single','deepSlots':6,'strategy':'fixture-frozen-strategy','files':[{'file':name,'bytes':len(raw),'sha256':sha(raw)}for name,raw in bodies.items()],'policy':m.POLICY};baseline=json.dumps({'schemaVersion':1,'kind':'poe-research-baseline-checkpoint','physicalSettlement':{'physicalTransportsSettled':True}}).encode();status=json.dumps({'accountId':m.ACCOUNT_ID,'inceptionAt':m.INCEPTION_ISO,'release':'bce3d22bb434eb429aafacb788a18f39ec189c1b'}).encode();value={'schemaVersion':1,'source':source,'dataContract':'confirmed-program-activity-v3-shadow','baselinePaths':['/var/lib/poe/native-engine/research-baseline.json'],'baselineCheckpointSha256':sha(baseline),'priorPhysicalSettled':True,'priorCooldownUntil':0,'origins':[],'reportingBinding':{'accountId':m.ACCOUNT_ID,'inceptionAt':m.INCEPTION,'sourceStatusSha256':sha(status)}}
   for name,raw in[('service.json',json.dumps(manifest).encode()),('input.json',json.dumps(value).encode()),('baseline.json',baseline),('status.json',status)]:(d/name).write_bytes(raw)
   args=[sys.executable,'-B','-I',str(HERE/'prepare-original-service-package.py'),'--bundle',str(bundle),'--service-manifest',str(d/'service.json'),'--input',str(d/'input.json'),'--baseline',str(d/'baseline.json'),'--original-status',str(d/'status.json'),'--output',str(d/'output')];result=subprocess.run(args,capture_output=True,text=True,timeout=5,check=True);receipt=json.loads(result.stdout);index=(d/'output/index.json').read_bytes();self.assertEqual(receipt['indexSha256'],sha(index));self.assertFalse(receipt['financialAccountOpened']);self.assertEqual(receipt['providerRequests'],0);self.assertFalse(receipt['hostDeployment']);self.assertEqual((d/'output/research-baseline.json').read_bytes(),baseline)
   for row in json.loads(index)['files']:self.assertEqual(row['sha256'],sha((d/'output'/row['file']).read_bytes()));self.assertEqual(row['bytes'],(d/'output'/row['file']).stat().st_size)
   command=shlex.split(receipt['ownerOnlyOneTimeCommandAfterVerifiedHostStaging']);self.assertEqual(command[:5],['sudo','/usr/bin/python3','-B','-I','-c']);compile(command[5],'<verified-owner-command>','exec');self.assertIn(receipt['driverSha256'],command[5]);self.assertIn(receipt['indexSha256'],command[5]);self.assertIn("exec(compile(b,p,'exec')",command[5]);self.assertIn('/var/tmp/poe-issue11-staging/cutover-original-service.py',command[5]);self.assertNotIn('init',command[5]);self.assertEqual((d/'output').stat().st_mode&0o777,0o700)
   # A second preparation never overwrites the reviewed closure.
   refused=subprocess.run(args,capture_output=True,text=True,timeout=5);self.assertNotEqual(refused.returncode,0);self.assertEqual((d/'output/index.json').read_bytes(),index)
if __name__=='__main__':unittest.main()
